import {parseStatement} from '../core/statements.js?v=20261101-v3b';
import {configSection,outstanding,ledgerBalance} from '../core/business.js?v=20261101-v3b';
export function install(ctx){
 const b=()=>ctx.business;let account='',status='pending';
 function bankPage(){if(!b().accounts.some(a=>a.id===account))account=b().accounts[0]?.id||'';ctx.shell(`${ctx.head('Extratos e conciliação','Confira os movimentos do banco e vincule cada valor ao lançamento correto.')}<div class="toolbar"><select id="bank-account" aria-label="Conta bancária">${b().accounts.map(a=>`<option value="${a.id}" ${account===a.id?'selected':''}>${ctx.esc(a.name)}${a.active?'':' · inativa'}</option>`).join('')}</select><select id="bank-status" aria-label="Situação da conciliação">${[['pending','Pendentes'],['matched','Conciliados'],['ignored','Ignorados'],['all','Todos']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select>${ctx.can('bank','import')?'<button class="primary" id="import-statement">Importar CSV / OFX</button>':''}${ctx.can('settings_finance')?'<button class="secondary" data-action="settings">Configurar contas e importação</button>':''}</div><div class="note">Importar o extrato não movimenta o caixa. Concilie uma baixa já registrada para vinculá-la, ou escolha um título em aberto para registrar o pagamento.</div><div id="bank-lines"></div>`);ctx.$('#bank-account').onchange=e=>{account=e.target.value;draw()};ctx.$('#bank-status').onchange=e=>{status=e.target.value;draw()};ctx.$('#import-statement')?.addEventListener('click',importDialog);draw()}
 function draw(){const rows=b().lines.filter(l=>l.account_id===account&&(status==='all'||l.status===status)).sort((a,z)=>z.posted_on.localeCompare(a.posted_on));const a=b().accounts.find(a=>a.id===account);ctx.$('#bank-lines').innerHTML=`${a?`<div class="mini-summary">Saldo registrado: <strong>${ctx.money(ledgerBalance(a,b().entries,b().settlements))}</strong> · ${rows.length} movimentos neste filtro</div>`:''}<section class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição do banco</th><th>Valor</th><th>Situação</th><th></th></tr></thead><tbody>${rows.map(l=>`<tr><td>${ctx.date(l.posted_on)}</td><td>${ctx.esc(l.description)}${l.ignore_reason?`<small>${ctx.esc(l.ignore_reason)}</small>`:''}</td><td class="${l.amount>0?'positive-text':'negative-text'}">${ctx.money(l.amount)}</td><td><span class="badge">${{pending:'Pendente',matched:'Conciliado',ignored:'Ignorado'}[l.status]}</span></td><td>${l.status==='pending'&&ctx.can('bank','reconcile')?`<button class="secondary small" data-reconcile="${l.id}">Conciliar</button>`:l.status==='ignored'&&ctx.can('bank','reconcile')?`<button class="secondary small" data-restore-line="${l.id}">Reabrir conferência</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:ctx.empty('Nenhum movimento neste filtro.','Importe um arquivo CSV ou OFX para começar a conferência.')}</section>`;document.querySelectorAll('[data-reconcile]').forEach(el=>el.onclick=()=>reconcileDialog(el.dataset.reconcile));document.querySelectorAll('[data-restore-line]').forEach(el=>el.onclick=async()=>{el.disabled=true;try{await ctx.rpc('restore_bank_line',{p_line:el.dataset.restoreLine});await ctx.load();bankPage();ctx.toast('Movimento disponível para nova conferência.')}catch(err){ctx.toast(err.message);el.disabled=false}})}
 function importDialog(){if(!b().accounts.some(a=>a.active)){ctx.toast('Cadastre ou ative uma conta em Configurações → Financeiro e extratos antes de importar.');return}const c=configSection(ctx.settings,'finance'),d=ctx.modal('Importar extrato bancário',`<form><div class="grid2"><label class="field">Conta de destino<select name="account" required>${ctx.accountsOptions()}</select></label><label class="field">Arquivo CSV ou OFX · até 5 MB<input type="file" name="file" accept=".csv,.ofx,text/csv" required></label></div><p class="note">O CSV usa o modelo definido em Configurações → Financeiro e extratos. OFX usa os campos bancários do próprio arquivo. Revise os valores antes de confirmar.</p><div id="import-preview"></div><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button type="button" class="secondary" id="preview-statement">Ler e conferir</button><button class="primary" disabled id="confirm-import">Confirmar importação</button></div></form>`,{wide:true});d.querySelector('[name="account"]').value=account;let parsed=null,file=null,hash='';const reset=()=>{parsed=null;d.querySelector('#confirm-import').disabled=true;d.querySelector('#import-preview').innerHTML=''};d.querySelector('[name="file"]').onchange=reset;d.querySelector('[name="account"]').onchange=reset;
  d.querySelector('#preview-statement').onclick=async()=>{reset();try{file=d.querySelector('[name="file"]').files[0];if(!file||file.size>5000000)throw Error('Selecione um arquivo de até 5 MB.');let content=await file.text();if(content.includes('\uFFFD'))content=new TextDecoder('windows-1252').decode(await file.arrayBuffer());parsed=parseStatement(content,file.name,c);hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(content))),x=>x.toString(16).padStart(2,'0')).join('');const selected=d.querySelector('[name="account"]').value,existing=new Set(b().lines.filter(l=>l.account_id===selected).map(l=>l.external_id));d.querySelector('#import-preview').innerHTML=`<p><strong>${parsed.lines.length} movimentos</strong> · Entradas ${ctx.money(parsed.income)} · Saídas ${ctx.money(Math.abs(parsed.expense))}</p><p>${parsed.lines.filter(l=>existing.has(l.external_id)).length} movimentos já importados serão ignorados.</p>${parsed.errors.length?`<div class="error">Corrija o arquivo: ${parsed.errors.slice(0,10).map(e=>'linha '+e.line+': '+ctx.esc(e.message)).join('<br>')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição · primeiras 30 linhas</th><th>Valor</th></tr></thead><tbody>${parsed.lines.slice(0,30).map(l=>`<tr><td>${ctx.date(l.date)}</td><td>${ctx.esc(l.description)}</td><td>${ctx.money(l.amount)}</td></tr>`).join('')}</tbody></table></div><p class="note">CSV sem identificador usa data, descrição, valor e ocorrência para detectar repetições. Em arquivos com períodos sobrepostos, confira movimentos idênticos antes de conciliar.</p>`;d.querySelector('#confirm-import').disabled=!!parsed.errors.length||!parsed.lines.length;d.querySelector('.error[role="alert"]').textContent=''}catch(e){d.querySelector('.error[role="alert"]').textContent=e.message}};
  d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!parsed||parsed.errors.length)return;e.submitter.disabled=true;try{const result=await ctx.rpc('import_bank_lines',{p_account:d.querySelector('[name="account"]').value,p_name:file.name,p_hash:hash,p_lines:parsed.lines});await ctx.load();d.close();bankPage();ctx.toast(`${result.imported} movimentos importados; ${result.duplicates} repetidos ignorados.`)}catch(err){d.querySelector('.error[role="alert"]').textContent=err.message;e.submitter.disabled=false}};
 }
 function reconcileDialog(id){const l=b().lines.find(x=>x.id===id),kind=l.amount>0?'income':'expense',value=Math.abs(Number(l.amount)),cfg=configSection(ctx.settings,'finance');const near=date=>Math.abs(new Date(date)-new Date(l.posted_on))/86400000<=cfg.reconcile_days;const paid=b().settlements.filter(s=>!s.reversed&&!s.statement_id&&s.account_id===l.account_id&&Number(s.amount)===value&&b().entries.find(e=>e.id===s.entry_id)?.kind===kind).sort((a,z)=>Number(near(z.paid_on))-Number(near(a.paid_on)));const open=b().entries.filter(e=>!e.voided&&e.kind===kind&&outstanding(e,b().settlements)>=value).sort((a,z)=>Number(near(z.due_date))-Number(near(a.due_date)));
  const d=ctx.modal('Conciliar movimento',`<form><p><strong>${ctx.esc(l.description)}</strong><br>${ctx.date(l.posted_on)} · ${ctx.money(l.amount)}</p><label class="field">Como conciliar?<select name="mode"><option value="paid">Vincular a pagamento / recebimento já registrado</option><option value="open">Baixar título em aberto</option>${ctx.can('finance','create')?'<option value="new">Criar lançamento e registrar a baixa</option>':''}<option value="ignore">Ignorar movimento com justificativa</option></select></label><div data-mode="paid"><label class="field">Baixa do mesmo valor e da mesma conta<select name="paid"><option value="">Selecione…</option>${paid.map(s=>`<option value="${s.id}">${ctx.date(s.paid_on)} · ${ctx.esc(b().entries.find(e=>e.id===s.entry_id)?.description)}${near(s.paid_on)?' · data próxima':''}</option>`).join('')}</select></label><p class="note">Vincular não gera uma segunda entrada ou saída no caixa.</p></div><div data-mode="open" hidden><label class="field">Título com saldo suficiente<select name="entry"><option value="">Selecione…</option>${open.map(e=>`<option value="${e.id}">${ctx.esc(e.description)} · saldo ${ctx.money(outstanding(e,b().settlements))} · ${ctx.date(e.due_date)}</option>`).join('')}</select></label><p class="note">A baixa será registrada pela data do extrato. O saldo restante do título continuará em aberto.</p></div><div data-mode="new" hidden><div class="grid2"><label class="field">Classificação<select name="class">${ctx.groupOptions(kind==='income'?'revenue':'expense')}</select></label>${ctx.categoryInput()}${ctx.field('Cliente / fornecedor / sócio','party','text','','maxlength="200"')}</div></div><div data-mode="ignore" hidden><label class="field">Motivo<textarea name="reason" maxlength="1000"></textarea></label></div><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary">Confirmar conciliação</button></div></form>`,{wide:true});const form=d.querySelector('form');form.elements.category.required=false;form.elements.mode.onchange=()=>d.querySelectorAll('[data-mode]').forEach(el=>el.hidden=el.dataset.mode!==form.elements.mode.value);const request=crypto.randomUUID();form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const fd=new FormData(form),mode=fd.get('mode');if(mode==='ignore')await ctx.rpc('ignore_bank_line',{p_line:id,p_reason:fd.get('reason')});else{if(mode==='paid'&&!fd.get('paid')||mode==='open'&&!fd.get('entry'))throw Error('Escolha o lançamento correspondente.');if(mode==='new'&&!fd.get('category').trim())throw Error('Informe a categoria.');await ctx.rpc('reconcile_bank_line',{p_line:id,p_entry:mode==='open'?fd.get('entry'):null,p_settlement:mode==='paid'?fd.get('paid'):null,p_new:mode==='new'?{class:fd.get('class'),category:fd.get('category'),party:fd.get('party')}:null,p_request:request})}await ctx.load();d.close();bankPage();ctx.toast('Movimento conferido.')}catch(err){d.querySelector('.error').textContent=err.message;e.submitter.disabled=false}};
 }
 Object.assign(ctx,{bankPage});
}
